package com.dunerealms.bank;
import com.example.dunegui.NativeMenus;
import org.bukkit.Bukkit;import org.bukkit.inventory.Inventory;import org.bukkit.command.*;import org.bukkit.entity.Player;import org.bukkit.plugin.java.JavaPlugin;
import java.sql.*;import java.math.BigDecimal;import java.lang.reflect.*;import java.util.*;import java.util.concurrent.*;import java.util.function.Consumer;
public final class DuneBank extends JavaPlugin implements CommandExecutor{
 private JavaPlugin core;private Driver driver;private String url;private Properties auth;private volatile boolean ready;
 private final BankStore store=new BankStore();private final Set<UUID> busy=new HashSet<>();
 private final ExecutorService worker=Executors.newFixedThreadPool(2,r->{Thread t=new Thread(r,"DuneBank-reader");t.setDaemon(true);return t;});
 public void onEnable(){saveDefaultConfig();core=(JavaPlugin)getServer().getPluginManager().getPlugin("DuneCore");getCommand("dunebank").setExecutor(this);getCommand("staffbank").setExecutor(this);
  try{var settings=getConfig();if(settings.getString("database.jdbc-url","").isBlank())settings=core.getConfig();url=settings.getString("database.jdbc-url","");if(!url.startsWith("jdbc:mysql:"))throw new IllegalStateException();auth=new Properties();auth.setProperty("user",settings.getString("database.username",""));auth.setProperty("password",settings.getString("database.password",""));auth.setProperty("connectTimeout","3000");auth.setProperty("socketTimeout","5000");auth.setProperty("allowPublicKeyRetrieval","true");driver=(Driver)Class.forName("com.mysql.cj.jdbc.Driver",true,core.getClass().getClassLoader()).getDeclaredConstructor().newInstance();worker.execute(()->{try(Connection c=connect()){BankStore.initialize(c);ready=true;getLogger().info("Dunemarks banks ready; balances start at zero.");}catch(Exception e){getLogger().severe("Bank storage unavailable; transfers disabled.");}});}catch(Exception e){getLogger().severe("Private MySQL configuration required; bank transfers disabled.");}}
 public void onDisable(){ready=false;worker.shutdown();try{if(!worker.awaitTermination(5,TimeUnit.SECONDS))worker.shutdownNow();}catch(InterruptedException e){worker.shutdownNow();Thread.currentThread().interrupt();}}
 private Connection connect()throws SQLException{return driver.connect(url,auth);}
 public boolean onCommand(CommandSender sender,Command command,String label,String[] args){if(!(sender instanceof Player p)){sender.sendMessage("Open your bank in game.");return true;}if(args.length>0&&args[0].equalsIgnoreCase("faction")){if(entryAllowed(p,false))openFaction(p);else p.sendMessage("Bank menu access denied.");return true;}boolean staff=command.getName().equals("staffbank")||(args.length>0&&args[0].equalsIgnoreCase("staff"));if(!entryAllowed(p,staff)){p.sendMessage("Bank menu access denied.");return true;}open(p,staff);return true;}
 private void main(Runnable r){if(isEnabled())getServer().getScheduler().runTask(this,r);}
 record View(BigDecimal bank,BigDecimal wallet,List<BankStore.Entry> ledger,BankStore.Access access){}
 private void open(Player p,boolean staff){if(!p.isOnline()||!entryAllowed(p,staff))return;if(!ready){p.sendMessage("Bank storage is starting or unavailable. Try again shortly.");return;}UUID player=p.getUniqueId();if(!busy.add(player))return;Inventory loading=loading(p,staff);worker.execute(()->{try(Connection c=connect()){c.setAutoCommit(false);BankStore.Access access=staff?store.permissions(c,player):new BankStore.Access(true,true,true);if(!access.view())throw new SQLException("Staff bank access denied.");View v=new View(store.balance(c,player,staff,false),store.wallet(c,player),store.ledger(c,player,staff),access);c.rollback();main(()->{busy.remove(player);if(current(p,staff,loading))show(p,staff,v);});}catch(Exception e){main(()->{busy.remove(player);if(current(p,staff,loading))p.sendMessage("Bank unavailable or access denied. No funds moved.");});}});}
 private void openFaction(Player p){if(!ready||!p.isOnline()||!entryAllowed(p,false)||!busy.add(p.getUniqueId()))return;UUID player=p.getUniqueId();Inventory loading=loading(p,false);worker.execute(()->{try(Connection c=connect()){c.setAutoCommit(false);BankStore.FactionView v=store.faction(c,player);c.rollback();main(()->{busy.remove(player);if(current(p,false,loading))NativeMenus.show(this,p,"Faction Dunemarks Bank",v.faction()+"\nBalance: "+v.balance().toPlainString()+" Dunemarks\nRead-only treasury view.\n\n"+history(v.ledger()),List.of(choice(p,false,"Refresh","Read your current faction treasury.",()->openFaction(p)),choice(p,false,"Personal bank","Return to your personal bank.",()->open(p,false))));});}catch(Exception e){main(()->{busy.remove(player);if(current(p,false,loading))p.sendMessage("Faction treasury unavailable. Choose a faction first; no funds moved.");});}});}
 static Set<BigDecimal> amounts(BigDecimal available){BigDecimal cap=available.min(new BigDecimal("1000000.00"));Set<BigDecimal> values=new LinkedHashSet<>();for(BigDecimal n:List.of(new BigDecimal("10.00"),new BigDecimal("100.00"),cap))if(n.signum()>0&&n.compareTo(cap)<=0)values.add(n.setScale(2));return values;}
 private String history(List<BankStore.Entry> entries){return String.join("\n",entries.stream().map(e->e.action()+" | "+e.delta().toPlainString()+" DM -> "+e.balance().toPlainString()+" DM").toList());}
 private void show(Player p,boolean staff,View v){if(!entryAllowed(p,staff))return;String title=staff?"Imperial Network Staff Bank":"Personal Dunemarks Bank";String body="Bank: "+v.bank.toPlainString()+" Dunemarks\nYour wallet: "+v.wallet.toPlainString()+" Dunemarks\nNo interest or automatic grants.";List<NativeMenus.Choice> choices=new ArrayList<>();
  if(v.access.deposit()&&(!staff||p.hasPermission("dunebank.staff.deposit")))for(BigDecimal n:amounts(v.wallet))choices.add(choice(p,staff,"Deposit "+n.toPlainString()+" Dunemarks","Move wallet funds into this bank.",()->confirm(p,staff,false,n)));
  if(v.access.withdraw()&&(!staff||p.hasPermission("dunebank.staff.manage")))for(BigDecimal n:amounts(v.bank))choices.add(choice(p,staff,"Withdraw "+n.toPlainString()+" Dunemarks","Move bank funds into your wallet.",()->confirm(p,staff,true,n)));
  choices.add(choice(p,staff,"Ledger","Recent confirmed transfers.",()->NativeMenus.show(this,p,title+" - Ledger",history(v.ledger),List.of(choice(p,staff,"Back","Return to the bank.",()->open(p,staff))))));
  if(!staff)choices.add(choice(p,staff,"Faction treasury","Read-only view of your current faction bank.",()->openFaction(p)));
  choices.add(choice(p,staff,"Refresh","Read current balances.",()->open(p,staff)));NativeMenus.show(this,p,title,body,choices);}
 private Inventory loading(Player p,boolean staff){Inventory model=Bukkit.createInventory(null,9,"Bank - Loading");NativeMenus.inventory(this,p,"Bank - Loading",model,Map.of(),()->p.isOnline()&&entryAllowed(p,staff));return model;}
 static boolean current(Player p,boolean staff,Inventory model){return p.isOnline()&&entryAllowed(p,staff)&&NativeMenus.isCurrent(p,model);}
 static Runnable guarded(Player p,boolean staff,Runnable action){return ()->{if(p.isOnline()&&entryAllowed(p,staff))action.run();else p.sendMessage("Bank menu access changed. Reopen your current account menu.");};}
 private NativeMenus.Choice choice(Player p,boolean staff,String title,String description,Runnable action){return new NativeMenus.Choice(title,description,guarded(p,staff,action));}
 static boolean entryAllowed(Player p,boolean staff){return p.hasPermission("dunebank.use")&&(!staff||p.hasPermission("dunebank.staff.view"));}
 static boolean transferAllowed(Player p,boolean staff,boolean withdraw){return entryAllowed(p,staff)&&(!staff||p.hasPermission(withdraw?"dunebank.staff.manage":"dunebank.staff.deposit"));}
 private void confirm(Player p,boolean staff,boolean withdraw,BigDecimal n){UUID reference=UUID.randomUUID();NativeMenus.show(this,p,"Confirm Dunemarks Transfer",(withdraw?"Withdraw ":"Deposit ")+n.toPlainString()+" Dunemarks\n"+(staff?"Central network staff account":"Your personal bank"),List.of(choice(p,staff,"Confirm","Fresh funds and staff authority checked again.",()->transfer(p,staff,withdraw,n,reference)),choice(p,staff,"Cancel","No funds move.",()->open(p,staff))));}
 private static final class Failure extends RuntimeException{Failure(Exception e){super(e);}}
 private void transfer(Player p,boolean staff,boolean withdraw,BigDecimal n,UUID ref){if(!ready||!p.isOnline()||!transferAllowed(p,staff,withdraw)||!busy.add(p.getUniqueId()))return;try{Method api=core.getClass().getMethod("transactNetworkInventory",Player.class,Consumer.class);api.invoke(core,p,(Consumer<Connection>)c->{try{if(!transferAllowed(p,staff,withdraw))throw new SQLException("Native bank access revoked.");store.transfer(c,p.getUniqueId(),staff,withdraw,n,ref);}catch(Exception e){throw new Failure(e);}});p.sendMessage("Dunemarks transfer confirmed.");}catch(Exception e){p.sendMessage("Transfer could not be confirmed. Refresh before retrying; no duplicate transfer will be applied.");}finally{busy.remove(p.getUniqueId());}if(p.isOnline())open(p,staff);}
}
